package com.ultron.launcher;
import android.app.*;import android.content.*;import android.os.*;import android.security.keystore.*;import android.util.AtomicFile;import org.json.*;
import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.io.*;import java.security.*;import java.time.*;import java.time.format.*;import java.util.*;
/** Private encrypted file: ciphertext is atomically committed; the AES key stays in Android Keystore. */
public final class AgendaStore {
 private static final Object LOCK=new Object();private static final String ALIAS="ultron.agenda.aes.v1";
 private static javax.crypto.SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias(ALIAS))return(javax.crypto.SecretKey)ks.getKey(ALIAS,null);KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setRandomizedEncryptionRequired(true).build());return g.generateKey();}
 private static AtomicFile file(Context c){return new AtomicFile(new File(c.getFilesDir(),"ultron-agenda-v1.enc"));}
 private static JSONArray read(Context c)throws Exception{AtomicFile f=file(c);byte[] bytes;try{bytes=f.readFully();}catch(FileNotFoundException e){if(!f.getBaseFile().exists()&&!new File(f.getBaseFile().getPath()+".bak").exists())return new JSONArray();throw e;}if(bytes.length<29||bytes[0]!=1)throw new IOException("Formato agenda non valido");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(bytes,1,13)));return new JSONArray(new String(cipher.doFinal(Arrays.copyOfRange(bytes,13,bytes.length)),"UTF-8"));}
 private static void write(Context c,JSONArray rows)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());ByteArrayOutputStream bytes=new ByteArrayOutputStream();bytes.write(1);bytes.write(cipher.getIV());bytes.write(cipher.doFinal(rows.toString().getBytes("UTF-8")));AtomicFile f=file(c);FileOutputStream out=null;try{out=f.startWrite();out.write(bytes.toByteArray());f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}
 public static JSONArray list(Context c)throws Exception{synchronized(LOCK){return read(c);}}
 public static long parseTime(String date,String time,String zone){LocalDateTime local=LocalDateTime.parse(date+"T"+time,DateTimeFormatter.ISO_LOCAL_DATE_TIME);ZoneId id=ZoneId.of(zone);java.util.List<ZoneOffset> offsets=id.getRules().getValidOffsets(local);if(offsets.size()!=1)throw new IllegalArgumentException("Orario ambiguo o inesistente per il cambio dell’ora: scegli un altro orario.");return local.toInstant(offsets.get(0)).toEpochMilli();}
 public static JSONObject save(Context c,JSONObject input)throws Exception{synchronized(LOCK){
  JSONArray rows=read(c);if(rows.length()>=2000)throw new IllegalArgumentException("Limite di 2000 eventi raggiunto.");
  String title=input.optString("title","").trim(),kind=input.optString("kind","");if(title.isEmpty()||title.length()>160||!(kind.equals("event")||kind.equals("shift")))throw new IllegalArgumentException("Titolo o tipo di evento non valido.");
  String zone=ZoneId.systemDefault().getId(),date=input.getString("date"),startTime=input.getString("start"),endTime=input.getString("end");String endDate=LocalDate.parse(date).plusDays(input.optBoolean("overnight",false)?1:0).toString();
  long start=parseTime(date,startTime,zone),end=parseTime(endDate,endTime,zone);int pause=input.optInt("pause",0),reminder=input.optInt("reminder",-1);
  if(end<=start||end-start>172800000L||pause<0||pause*60000L>=end-start||reminder< -1||reminder>10080)throw new IllegalArgumentException("Controlla orari, pausa e preavviso.");
  if(reminder>=0&&start>System.currentTimeMillis()&&start-reminder*60000L<=System.currentTimeMillis())throw new IllegalArgumentException("Il preavviso è già passato: scegli All’inizio oppure un preavviso più breve.");
  String id=input.optString("id","");if(id.isEmpty())id=UUID.randomUUID().toString();else if(!id.matches("[0-9a-f-]{36}"))throw new IllegalArgumentException("Evento non valido.");
  JSONArray updated=new JSONArray();boolean found=input.optString("id","").isEmpty();
  for(int i=0;i<rows.length();i++){JSONObject old=rows.getJSONObject(i);if(old.getString("id").equals(id)){found=true;continue;}if(kind.equals("shift")&&old.optString("kind").equals("shift")&&start<old.getLong("endMs")&&end>old.getLong("startMs"))throw new IllegalArgumentException("Questo turno si sovrappone a un turno già salvato.");updated.put(old);}
  if(!found)throw new IllegalArgumentException("Evento non trovato.");
  JSONObject row=new JSONObject();row.put("id",id).put("title",title).put("kind",kind).put("date",date).put("start",startTime).put("end",endTime).put("overnight",input.optBoolean("overnight",false)).put("zone",zone).put("startMs",start).put("endMs",end).put("pause",pause).put("reminder",reminder).put("ring",input.optBoolean("ring",false));updated.put(row);write(c,updated);cancel(c,id);schedule(c,row);return row;
 }}
 public static void delete(Context c,String id)throws Exception{synchronized(LOCK){JSONArray rows=read(c),out=new JSONArray();for(int i=0;i<rows.length();i++)if(!rows.getJSONObject(i).getString("id").equals(id))out.put(rows.getJSONObject(i));write(c,out);cancel(c,id);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(id,1);}}
 private static PendingIntent pending(Context c,String id){return PendingIntent.getBroadcast(c,0,new Intent(c,AgendaReceiver.class).setAction("com.ultron.launcher.AGENDA").setData(android.net.Uri.parse("ultron-agenda://event/"+id)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public static void cancel(Context c,String id){if(id.equals(AgendaAlarmService.activeId))c.stopService(new Intent(c,AgendaAlarmService.class));((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).cancel(pending(c,id));}
 public static boolean exact(Context c){return Build.VERSION.SDK_INT<31||((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).canScheduleExactAlarms();}
 public static boolean notifications(Context c){return(Build.VERSION.SDK_INT<33||c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==android.content.pm.PackageManager.PERMISSION_GRANTED)&&((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).areNotificationsEnabled();}
 public static void schedule(Context c,JSONObject row)throws Exception{int reminder=row.optInt("reminder",-1);long at=row.getLong("startMs")-reminder*60000L;if(reminder<0||at<=System.currentTimeMillis()||!exact(c)||!notifications(c))return;try{((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending(c,row.getString("id")));}catch(SecurityException ignored){}}
 public static void reschedule(Context c)throws Exception{synchronized(LOCK){JSONArray rows=read(c);for(int i=0;i<rows.length();i++)schedule(c,rows.getJSONObject(i));}}
}
